import * as http from 'node:http';
function main(): void {
const M: any = http;
console.log(typeof M.IncomingMessage, typeof M.Server, typeof M.OutgoingMessage, typeof M.ClientRequest, typeof M.Agent, typeof M.ServerResponse);
console.log(M.METHODS.length, Object.keys(M.STATUS_CODES).length, M.STATUS_CODES[418], M.STATUS_CODES[511], M.METHODS.includes('QUERY'));
const o = new M.OutgoingMessage();
console.log(o.sendDate, o.chunkedEncoding, o.writable, o.finished, o.headersSent, o.destroyed, o.shouldKeepAlive, o.useChunkedEncodingByDefault, o.writableEnded);
console.log(o.setHeader('A', 1) === o, o.getHeaderNames().join(','), o.hasHeader('a'), o.getHeader('a'));
console.log(o instanceof M.OutgoingMessage, M.Agent.length, new M.Agent({ keepAlive: true, maxSockets: 2 }).maxSockets);
}
